insert into public.role_permissions(role,permission_key,is_enabled) values ('admin','admin:approve_admin_requests',true),('admin_dir','admin:approve_admin_requests',true),('admin_acct','admin:approve_admin_requests',true),('super_admin','admin:approve_admin_requests',true),('admin_it','admin:approve_admin_requests',true) on conflict(role,permission_key) do update set is_enabled=true,updated_at=now();
create or replace function public.can_approve_admin_request(_user_id uuid default auth.uid()) returns boolean language sql stable security definer set search_path=public as $$ select coalesce(public.user_has_permission(_user_id,'admin:approve_admin_requests') or public.user_has_permission(_user_id,'admin:manage_users') or public.user_has_permission(_user_id,'admin:manage_departments') or public.user_has_permission(_user_id,'admin:all'),false); $$;
revoke all on function public.can_approve_admin_request(uuid) from public;
grant execute on function public.can_approve_admin_request(uuid) to authenticated;
